def line(prefix,value):
 global h
 lines=h.splitlines()
 for i,l in enumerate(lines):
  if l.startswith(prefix):lines[i]=value;h='\n'.join(lines)+'\n';return
 raise ValueError(prefix)
def function(start,nextstart,value):
 global h
